import java.util.*;

enum GameState { IN_PROGRESS, WON, DRAWN }

record Position(int row, int col) {}
record Player(String playerId, String name, char symbol) {}

class Board {
    private final int rows;
    private final int cols;
    private final Player[][] grid;

    public Board(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new Player[rows][cols];
    }

    public Player getCell(Position p) {
        if (!inBounds(p)) return null;
        return grid[p.row()][p.col()];
    }

    public void setCell(Position p, Player player) {
        if (!inBounds(p))
            throw new IndexOutOfBoundsException("Position out of bounds: " + p);
        grid[p.row()][p.col()] = player;
    }

    public boolean isEmpty(Position p) {
        return inBounds(p) && grid[p.row()][p.col()] == null;
    }

    public boolean inBounds(Position p) {
        return p.row() >= 0 && p.row() < rows && p.col() >= 0 && p.col() < cols;
    }

    public boolean isFull() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == null) return false;
            }
        }
        return true;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }

    // Utility for debugging / display
    public String render() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                Player p = grid[r][c];
                sb.append(p == null ? '.' : p.symbol());
                sb.append(' ');
            }
            sb.append('\n');
        }
        return sb.toString();
    }
}

public abstract class BoardGame {
    protected final Board board;
    protected final Player[] players = new Player[2];
    protected int currentPlayerIndex = 0;
    protected GameState state = GameState.IN_PROGRESS;
    protected Player winner;
    protected final List<Move> moveHistory = new ArrayList<>();

    protected BoardGame(Player player1, Player player2) {
        // Subclass provides board dimensions via getBoardSize()
        int[] size = getBoardSize();
        this.board = new Board(size[0], size[1]);
        this.players[0] = player1;
        this.players[1] = player2;
    }

    // ── Template method — the fixed game loop ──
    public final void makeMove(String playerId, Position position) {
        // 1. Game already over?
        if (state != GameState.IN_PROGRESS)
            throw new GameAlreadyOverException("Game is " + state);

        // 2. Right player's turn?
        Player currentPlayer = players[currentPlayerIndex];
        if (!currentPlayer.playerId().equals(playerId))
            throw new WrongTurnException(
                "Expected " + currentPlayer.name() + " to move");

        // 3. Valid move per game rules? (hook)
        if (!isValidMove(position))
            throw new InvalidMoveException("Invalid move: " + position);

        // 4. Apply the move (hook — may adjust position, e.g., Connect-Four drops)
        Position actualPosition = applyMove(currentPlayer, position);
        moveHistory.add(new Move(currentPlayer, actualPosition));

        // 5. Check win (hook)
        if (checkWinCondition(actualPosition)) {
            state = GameState.WON;
            winner = currentPlayer;
            return;
        }

        // 6. Check draw (generic — board full with no win)
        if (board.isFull()) {
            state = GameState.DRAWN;
            return;
        }

        // 7. Switch turns
        currentPlayerIndex = 1 - currentPlayerIndex;
    }

    // ── Abstract hooks — subclasses must provide ──

    // Board dimensions: [rows, cols]
    protected abstract int[] getBoardSize();

    // Is this a valid position to move to in this game?
    protected abstract boolean isValidMove(Position position);

    // Apply the move — may transform the position (e.g., Connect-Four drops)
    // Returns the actual final position on the board
    protected abstract Position applyMove(Player player, Position requested);

    // Did this move win the game?
    protected abstract boolean checkWinCondition(Position lastMove);

    // ── Public state accessors ──
    public GameState getState()           { return state; }
    public Player getWinner()             { return winner; }
    public Player getCurrentPlayer()      { return players[currentPlayerIndex]; }
    public Board getBoard()               { return board; }
    public List<Move> getMoveHistory()    { return Collections.unmodifiableList(moveHistory); }
}

record Move(Player player, Position position) {}

public class TicTacToe extends BoardGame {
    private static final int SIZE = 3;

    public TicTacToe(Player x, Player o) {
        super(x, o);
    }

    @Override
    protected int[] getBoardSize() {
        return new int[]{SIZE, SIZE};
    }

    @Override
    protected boolean isValidMove(Position pos) {
        return board.inBounds(pos) && board.isEmpty(pos);
    }

    @Override
    protected Position applyMove(Player player, Position requested) {
        board.setCell(requested, player);
        return requested; // no transformation
    }

    @Override
    protected boolean checkWinCondition(Position lastMove) {
        Player p = board.getCell(lastMove);
        int row = lastMove.row();
        int col = lastMove.col();

        // Row check
        boolean rowWin = true;
        for (int c = 0; c < SIZE; c++) {
            if (board.getCell(new Position(row, c)) != p) {
                rowWin = false;
                break;
            }
        }
        if (rowWin) return true;

        // Column check
        boolean colWin = true;
        for (int r = 0; r < SIZE; r++) {
            if (board.getCell(new Position(r, col)) != p) {
                colWin = false;
                break;
            }
        }
        if (colWin) return true;

        // Main diagonal (only if on diagonal)
        if (row == col) {
            boolean diagWin = true;
            for (int i = 0; i < SIZE; i++) {
                if (board.getCell(new Position(i, i)) != p) {
                    diagWin = false;
                    break;
                }
            }
            if (diagWin) return true;
        }

        // Anti-diagonal (only if on anti-diagonal)
        if (row + col == SIZE - 1) {
            boolean antiWin = true;
            for (int i = 0; i < SIZE; i++) {
                if (board.getCell(new Position(i, SIZE - 1 - i)) != p) {
                    antiWin = false;
                    break;
                }
            }
            if (antiWin) return true;
        }

        return false;
    }
}

public class ConnectFour extends BoardGame {
    private static final int ROWS = 6;
    private static final int COLS = 7;
    private static final int WIN_LENGTH = 4;

    public ConnectFour(Player red, Player yellow) {
        super(red, yellow);
    }

    @Override
    protected int[] getBoardSize() {
        return new int[]{ROWS, COLS};
    }

    @Override
    protected boolean isValidMove(Position pos) {
        // Connect-Four: only column matters. Valid if column exists and not full.
        int col = pos.col();
        if (col < 0 || col >= COLS) return false;
        // Column is full if the top row in that column is occupied
        return board.isEmpty(new Position(0, col));
    }

    @Override
    protected Position applyMove(Player player, Position requested) {
        int col = requested.col();
        // Drop to the lowest empty row in this column
        for (int row = ROWS - 1; row >= 0; row--) {
            Position p = new Position(row, col);
            if (board.isEmpty(p)) {
                board.setCell(p, player);
                return p; // actual landing position
            }
        }
        throw new IllegalStateException("Column full — should have been caught by isValidMove");
    }

    @Override
    protected boolean checkWinCondition(Position lastMove) {
        Player p = board.getCell(lastMove);
        // 4 directions: horizontal, vertical, two diagonals
        int[][] directions = {
            {0, 1},   // horizontal
            {1, 0},   // vertical
            {1, 1},   // diagonal ↘
            {1, -1}   // diagonal ↙
        };

        for (int[] dir : directions) {
            if (countInDirection(lastMove, p, dir[0], dir[1]) >= WIN_LENGTH)
                return true;
        }
        return false;
    }

    // Count consecutive pieces of 'player' through lastMove in the given direction
    // (both ways along the axis, since lastMove could be anywhere in the winning line)
    private int countInDirection(Position from, Player player, int dr, int dc) {
        int count = 1; // the piece at `from` itself

        // Forward direction
        int r = from.row() + dr, c = from.col() + dc;
        while (r >= 0 && r < ROWS && c >= 0 && c < COLS
                && board.getCell(new Position(r, c)) == player) {
            count++;
            r += dr;
            c += dc;
        }

        // Backward direction
        r = from.row() - dr;
        c = from.col() - dc;
        while (r >= 0 && r < ROWS && c >= 0 && c < COLS
                && board.getCell(new Position(r, c)) == player) {
            count++;
            r -= dr;
            c -= dc;
        }

        return count;
    }
}

// Tic-Tac-Toe game
Player alice = new Player("alice", "Alice", 'X');
Player bob = new Player("bob", "Bob", 'O');
TicTacToe ttt = new TicTacToe(alice, bob);

ttt.makeMove("alice", new Position(0, 0));  // X at top-left
ttt.makeMove("bob",   new Position(1, 1));  // O center
ttt.makeMove("alice", new Position(0, 1));  // X top-middle
ttt.makeMove("bob",   new Position(2, 2));  // O bottom-right
ttt.makeMove("alice", new Position(0, 2));  // X top-right — wins!

System.out.println(ttt.getState());  // WON
System.out.println(ttt.getWinner().name()); // Alice
System.out.println(ttt.getBoard().render());

// Connect-Four game — reuses the same engine
Player red = new Player("red", "Red", 'R');
Player yellow = new Player("yellow", "Yellow", 'Y');
ConnectFour c4 = new ConnectFour(red, yellow);

// Red drops in column 3; actual row is determined by applyMove
c4.makeMove("red", new Position(0, 3));
c4.makeMove("yellow", new Position(0, 2));
c4.makeMove("red", new Position(0, 3));
// ... continue play

System.out.println(c4.getBoard().render());
